// Parse Input  (mode: runOnceForAllItems)
const raw = $input.first().json;
let payload;
const bodyText = raw.body;
if (typeof bodyText === 'string') { try { payload = JSON.parse(bodyText); } catch (e) { payload = { description: bodyText }; } }
else if (bodyText && typeof bodyText === 'object') { payload = bodyText; }
else { payload = raw; }

let questions = payload.questions;
if (typeof questions === 'string') questions = questions.split('\n');
if (!Array.isArray(questions)) questions = [];
questions = questions.map(q => String(q || '').trim()).filter(Boolean).slice(0, 15);

// El cap era 8000 y con un slice de cabeza, que es el peor corte posible: los
// requisitos (idioma, residencia, anios pedidos) viven al final de la oferta.
// La extension ya manda las dos puntas cuando no entra, pero el workflow no
// puede confiar en que el cliente lo haya hecho: Telegram y cualquier otro
// caller entran por aca igual. Misma politica de los dos lados.
const MAX = 30000, HEAD = 8000, TAIL = 12000;
let description = (payload.description || '').toString();

// LinkedIn mete su selector de idiomas al final del texto de la pagina:
// decenas de lineas tipo "Portugues (Portuguese)", "Polski (Polish)". Eso no es
// parte del aviso y encima disparaba el bloqueo por idioma. Se corta cualquier
// corrida de 4 o mas lineas seguidas con esa forma.
description = description.replace(
  /(?:^[ \t]*\S[^\n]{0,28}\([A-Z][a-zA-Z]+\)[ \t]*\n){4,}/gm, '');
let truncated = !!payload.description_truncated;
const originalChars = Number(payload.description_chars_original) || description.length;

if (description.length > MAX) {
  const n = description.length;
  description = description.slice(0, HEAD) +
    '\n\n[... ' + (n - HEAD - TAIL) + ' caracteres omitidos del medio ...]\n\n' +
    description.slice(n - TAIL);
  truncated = true;
}

return [{
  json: {
    mode: (payload.mode === 'score' ? 'score' : 'apply'),
    // Toggle del panel. Por defecto true, asi cualquier caller viejo (Telegram)
    // sigue recibiendo la carta como antes.
    want_letter: payload.want_letter !== false,
    title: (payload.title || '').toString().substring(0, 300),
    company: (payload.company || '').toString().substring(0, 200),
    description: description,
    url: (payload.url || '').toString(),
    questions: questions,
    description_source: (payload.description_source || '').toString().substring(0, 120),
    description_truncated: truncated,
    description_chars_original: originalChars
  }
}];

// Build Prompt  (mode: runOnceForEachItem)
// El PERFIL ya no se hardcodea aca: viene de public.profile_facts filtrado por
// verified_bool, armado en Screen Blockers. Para corregir un dato del perfil se
// edita una fila en la base, no este nodo.

const job = $input.item.json;
const mode = job.mode || 'apply';
const PERFIL = job._perfil;
if (!PERFIL) throw new Error('Llegue sin _perfil: Screen Blockers no corrio');

// Reglas anti invencion. El modelo tiende a redondear y a inventar porcentajes
// que suenan bien, y eso despues se pega en una aplicacion real.
const REGLAS = [
  'REGLAS DURAS (no negociables):',
  '1. No escribas ningun numero, porcentaje, cantidad ni duracion que no aparezca textualmente en PERFIL. Prohibido derivar, redondear, sumar o inventar porcentajes.',
  '2. Si la oferta pide un dato numerico que no esta en PERFIL, escribi el placeholder [FALTA DATO: que falta] en vez de estimar.',
  '2bis. EXCEPCION UNICA a la regla 1: el campo salary_posted se copia TEXTUAL de la oferta. Es una cita, no una afirmacion tuya. Si la oferta no dice sueldo, salary_posted va vacio. Prohibido estimarlo, convertirlo de anual a mensual, o completarlo con lo que suele pagar el mercado.',
  '3. No uses guion largo ni guion medio. Usa coma, punto, dos puntos o parentesis.',
  '4. ORTOGRAFIA POR IDIOMA, las dos mitades importan:',
  '   - En INGLES: sin caracteres acentuados.',
  '   - En ESPANOL: ortografia COMPLETA y correcta. Acentos donde corresponde\n' +
  '     (automatización, gestión, integración, más, también, después, día,\n' +
  '     técnico, práctica, años) y la letra ñ donde va (español, diseño, año,\n' +
  '     enseñar, campaña). Una carta en espaniol sin acentos se lee como escrita\n' +
  '     por un bot y es motivo de descarte. NUNCA escribas "anios" ni "espaniol":\n' +
  '     se escriben "años" y "español".',
  '   Si el PERFIL o estas instrucciones tienen alguna palabra mal acentuada,\n' +
  '   corregila al escribir. No imites ese error.',
  '6. Nunca menciones la edad de Santiago ni el anio en que nacio.',
  '5. No inventes experiencia, clientes, herramientas ni empresas que no esten en PERFIL.'
].join('\n');

// La calibracion del fit NO se define aca: viene dentro del PERFIL, en la fila
// profile_facts.fit_calibration_rule, que es la MISMA que usa el pase diario de
// las 07:15. Antes cada camino tenia su propio criterio y el mismo aviso sacaba
// 92 en el panel y 72 en el board.
const TASK_SCORE = 'TAREA (modo SCORE): Evalua SOLO el fit del perfil con esta oferta. NO escribas cover letter ni respuestas.\n' +
  'Aplica la CALIBRACION DEL FIT SCORE que viene en el PERFIL, tal cual esta escrita, sin ablandarla ni endurecerla.\n' +
  'SUELDO ESTIMADO (salary_est): decime cuanto PAGA el puesto, no cuanto conviene pedir. Son dos cosas distintas y la segunda no entra aca.\n' +
  '1. Si el aviso publica sueldo, ese es el dato y no se toca: min y max son el rango del aviso tal cual (2500 a 3700 se guarda 2500 y 3700, no 3700 y 3700). Si publica un solo numero, min = max = ese numero. basis "publicado en el aviso", conf "alta". Aca NO se aplica la regla de cuanto conviene pedir: esa dice que pedir y este campo dice que paga.\n' +
  '2. Si no lo publica, elegi familia y seniority de la REFERENCIA DE MERCADO y angostá a un rango de EXACTAMENTE 500 USD de ancho con las senales del aviso: pais de la empresa, anios que pide, profundidad del stack, agencia o producto, full time o por horas.\n' +
  '3. basis nombra la familia y el nivel de la referencia y la senal que te movio dentro de la banda.\n' +
  '4. Si el aviso no alcanza para ubicarlo fino, ampliá hasta 1500 de ancho, conf "baja", y escribí en basis que falto. Un rango ancho honesto vale mas que uno angosto inventado. Dejá salary_est en null SOLO si no podes ni identificar la familia de rol; si podes nombrar la familia, siempre devolvé un rango.\n' +
  '5. PROHIBIDO un numero que no salga de la REFERENCIA DE MERCADO o del propio aviso.\n' +
  'Devolve SOLO JSON valido: {"job_title":"","company_name":"","language":"es|en","fit_score":0,"top_reasons":["r1","r2","r3"],"red_flags":["..."],"which_cv":"ES|EN","salary_est":{"min":0,"max":0,"basis":"","conf":"alta|media|baja"},"salary_posted":"el sueldo tal como lo publica el aviso, textual y con su moneda y periodo, o cadena vacia si el aviso no lo dice","salary_note":"una linea de como posicionar el salario, aplicando la REGLA DE SALARIO del PERFIL"}';

const TASK_APPLY = 'TAREA (modo APPLY): Escribi una cover letter y, si hay preguntas de la aplicacion, responde cada una.\n' +
  'cover_letter: 200-250 palabras, especifica a ESTA oferta, con logros REALES de PERFIL, en el idioma de la oferta, humana.\n' +
  'answers: para cada pregunta, respuesta en PRIMERA PERSONA como Santiago, en el idioma de la oferta, concreta y honesta. Preguntas si/no o numericas: directo y breve. Abiertas: 2-4 frases. Si no hay preguntas, [].\n' +
  'Devolve SOLO JSON valido: {"job_title":"","company_name":"","language":"es|en","which_cv":"ES|EN","salary_posted":"","salary_note":"","cover_letter":"...","answers":[{"question":"","answer":""}]}';

const TASK_APPLY_SIN_CARTA = 'TAREA (modo APPLY SIN COVER LETTER): NO escribas cover letter. Dejala como cadena vacia. Respondé unicamente las preguntas de la aplicacion.\n' +
  'answers: para cada pregunta, respuesta en PRIMERA PERSONA como Santiago, en el idioma de la oferta, concreta y honesta. Preguntas si/no o numericas: directo y breve. Abiertas: 2-4 frases.\n' +
  'Devolve SOLO JSON valido: {"job_title":"","company_name":"","language":"es|en","which_cv":"ES|EN","salary_posted":"","salary_note":"","cover_letter":"","answers":[{"question":"","answer":""}]}';

const q = Array.isArray(job.questions) ? job.questions.filter(x => x && String(x).trim()) : [];
const wantLetter = job.want_letter !== false;
const task = mode === 'score' ? TASK_SCORE : (wantLetter ? TASK_APPLY : TASK_APPLY_SIN_CARTA);

// 3000 cortaba el JSON a la mitad cuando la aplicacion tenia muchas preguntas.
// Sin carta el techo baja: una carta de 250 palabras es la mayor parte de la
// salida. 600 de base mas 350 por pregunta, entre 800 y 4000.
const maxTokens = mode === 'score' ? 1500
  : (wantLetter ? 8000 : Math.max(800, Math.min(4000, 600 + 350 * q.length)));
// La referencia de mercado solo hace falta cuando hay que estimar sueldo.
const MERCADO = job._mercado || '';
const system = PERFIL + '\n\n' + REGLAS + '\n\n' +
  (mode === 'score' && MERCADO ? MERCADO + '\n\n' : '') + task;

let user = 'OFERTA DE TRABAJO:\n' +
  (job.title ? ('Titulo: ' + job.title + '\n') : '') +
  (job.company ? ('Empresa: ' + job.company + '\n') : '') +
  (job.url ? ('URL: ' + job.url + '\n') : '');

if (job.description_truncated) {
  user += 'NOTA: la descripcion venia mas larga que el limite. Se conservaron el principio y el final, que es donde viven los requisitos. El medio se omitio y esta marcado.\n';
}
if (Array.isArray(job.frictions) && job.frictions.length) {
  user += 'FRICCIONES detectadas automaticamente (tenelas en cuenta, no las cites textual): ' +
    job.frictions.map(f => f.reason).join('; ') + '\n';
}

user += '\nTexto:\n' + job.description;

if (mode === 'apply' && q.length) {
  user += '\n\nPREGUNTAS DE LA APLICACION (responder cada una en answers):\n' +
    q.map((x, i) => (i + 1) + '. ' + x).join('\n');
}
user += '\n\nResponde UNICAMENTE con el objeto JSON pedido, sin texto adicional ni bloques de codigo markdown.';

// El modo SCORE no necesita Sonnet: es una clasificacion, y Haiku la hace igual
// de bien (lo comprueba el workflow de fit por IA, que corre con Haiku y acierta).
// Sonnet queda solo para APPLY, donde lo que se juega es la redaccion de la carta.
// Con 34 llamadas en dos dias, casi todas de score, esto es la diferencia entre
// dos dolares y unos centavos.
const MODELO = mode === 'score' ? 'claude-haiku-4-5' : 'claude-sonnet-4-6';

// SCORE va con temperature 0, APPLY se deja como estaba. Sin temperature la API
// usa 1 y el mismo aviso puntuado dos veces da numeros distintos: medido el
// 07/09 en el pase diario, el aviso 4575 dio 68, 68, 52, 68 en cuatro llamadas
// identicas. Una carta puede variar sin problema; un numero que decide si el
// aviso se promueve, no. Este es el segundo camino de scoring y tenia el mismo
// agujero que el pase diario.
const body = JSON.stringify(Object.assign({
  model: MODELO,
  max_tokens: maxTokens,
  system: system,
  messages: [{ role: 'user', content: user }]
}, mode === 'score' ? { temperature: 0 } : {}));

return { json: Object.assign({}, job, { _llm_body: body, mode: mode, _max_tokens: maxTokens }) };

// Parse & Format  (mode: runOnceForEachItem)

const job = $('Screen Blockers').item.json;
const mode = job.mode || 'apply';
const v = $input.item.json;
const s = v._llm;

const esc = (x) => String(x == null ? '' : x)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const title = String(job.title || s.job_title || 'Oferta').substring(0, 480);
const company = String(job.company || s.company_name || '').substring(0, 240);
const extId = job.external_id || String(job.url || ('cl-' + Date.now())).split('?')[0].substring(0, 255);

// ---- avisos que van arriba de todo, antes del texto
const avisos = [];
if (v.unverified_numbers && v.unverified_numbers.length) {
  avisos.push('⚠️ Numeros SIN respaldo en PERFIL: ' +
    v.unverified_numbers.map(u => u.number).join(', ') +
    ' — verificalos antes de mandar.');
}
if (job.description_truncated) {
  avisos.push('⚠️ Descripcion truncada (' + (job.description_chars_original || '?') +
    ' chars). Se mandaron el principio y el final.');
}
if (v._stop_reason === 'max_tokens') {
  avisos.push('⚠️ La respuesta se corto por limite de tokens.');
}
if (v._parse_error) {
  avisos.push('⚠️ El modelo no devolvio JSON valido: ' + v._parse_error);
}
if (job.description_source && job.description_source === 'body-fallback') {
  avisos.push('⚠️ La descripcion salio del fallback del body, puede traer ruido.');
}
if (Array.isArray(job.frictions) && job.frictions.length) {
  avisos.push('• Fricciones: ' + job.frictions.map(f => f.reason).join('; '));
}

if (mode === 'score') {
  return {
    json: {
      mode: 'score', source: 'linkedin_score', external_id: extId,
      title: title, company: company, url: job.url || '',
      description: String(job.description || '').substring(0, 4000),
      score: Number(s.fit_score) || 0, verdict: s.language || '',
      top_reasons: s.top_reasons || [], red_flags: s.red_flags || [],
      recommendation: s.which_cv || '',
      salary_posted: String(s.salary_posted || '').substring(0, 120),
      salary_est_min: (s.salary_est && s.salary_est.min != null) ? Math.round(Number(s.salary_est.min) || 0) : '',
      salary_est_max: (s.salary_est && s.salary_est.max != null) ? Math.round(Number(s.salary_est.max) || 0) : '',
      salary_est_basis: String((s.salary_est && s.salary_est.basis) || '').substring(0, 400),
      // Mismo criterio que el trigger de la base: un rango ancho no puede
      // declararse "media". Si no se aplicara aca, el panel diria una confianza
      // y el board otra para la misma fila.
      salary_est_conf: (function () {
        const e = s.salary_est || {};
        const c = String(e.conf || '').toLowerCase();
        const ancho = (Number(e.max) || 0) - (Number(e.min) || 0);
        if (e.min == null || e.max == null) return c;
        return ancho > 600 ? 'baja' : (c || 'media');
      })(),
      salary_range: String(s.salary_posted || '').substring(0, 255),
      status: 'scored',
      fit_score: Number(s.fit_score) || 0, which_cv: s.which_cv || '',
      language: s.language || '', salary_note: s.salary_note || '',
      unverified_numbers: v.unverified_numbers || [],
      description_truncated: !!job.description_truncated,
      description_source: job.description_source || '',
      frictions: job.frictions || [],
      blocked: false,
      telegram_chunks: []
    }
  };
}

const answers = Array.isArray(s.answers) ? s.answers : [];

// ---- Telegram en varios mensajes
// Telegram corta en 4096 caracteres. Antes, si la aplicacion tenia muchas
// preguntas, el mensaje se reemplazaba por "ve la extension" y las respuestas
// no se veian en ningun lado. Ahora se parte y se manda una atras de otra.
const partes = [];
if (avisos.length) partes.push(avisos.map(esc).join('\n'));
partes.push('📝 <b>' + esc(title) + '</b>\n🏢 ' + esc(company) +
  '\nCV: ' + esc(s.which_cv || '') + '  |  ' + esc(String(s.language || '').toUpperCase()));
if (String(s.cover_letter || '').trim()) {
  partes.push('✉️ <b>Cover letter:</b>\n' + esc(s.cover_letter));
}
answers.forEach((a, i) => {
  partes.push('❓ <b>' + (i + 1) + '. ' + esc(a.question) + '</b>\n' + esc(a.answer));
});

const LIMITE = 3500;
const chunks = [];
let actual = '';
for (const p of partes) {
  // una parte sola mas larga que el limite se corta por lineas
  if (p.length > LIMITE) {
    if (actual) { chunks.push(actual); actual = ''; }
    let resto = p;
    while (resto.length > LIMITE) {
      let corte = resto.lastIndexOf('\n', LIMITE);
      if (corte < LIMITE * 0.5) corte = LIMITE;
      chunks.push(resto.slice(0, corte));
      resto = resto.slice(corte).replace(/^\n/, '');
    }
    if (resto) actual = resto;
    continue;
  }
  if ((actual + '\n\n' + p).length > LIMITE) { chunks.push(actual); actual = p; }
  else { actual = actual ? (actual + '\n\n' + p) : p; }
}
if (actual) chunks.push(actual);

const total = chunks.length;
const numerados = chunks.map((c, i) => (total > 1 ? ('<i>(' + (i + 1) + '/' + total + ')</i>\n') : '') + c);

return {
  json: {
    mode: 'apply', external_id: extId, title: title, company: company, url: job.url || '',
    which_cv: s.which_cv || '', language: s.language || '', salary_note: s.salary_note || '',
    salary_posted: String(s.salary_posted || '').substring(0, 120),
    cover_letter: s.cover_letter || '', answers: answers,
    unverified_numbers: v.unverified_numbers || [],
    description_truncated: !!job.description_truncated,
    description_source: job.description_source || '',
    frictions: job.frictions || [],
    blocked: false,
    stop_reason: v._stop_reason || '',
    telegram_chunks: numerados,
    telegram_message: numerados[0] || ''
  }
};

const m = $input.first().json;
const text = (m.message && m.message.text) || m.text || '';
return [{ json: { mode: 'apply', title: '', company: '', description: String(text).substring(0, 8000), url: '', questions: [] } }];

// Screen Blockers  (mode: runOnceForAllItems)
// Entra: filas de profile_facts (Load Profile). Sale: UN item con el job, el
// PERFIL armado y el resultado del screening.
//
// Port de scripts/screen.py de la skill job-hunt. La idea es no gastar una
// llamada a Claude en una oferta que ya esta descartada, y dejar la razon
// escrita en la fila para que despues se pueda auditar.

// ---- job de origen: webhook de la extension o trigger de Telegram
let job = null;
try { job = $('Parse Input').first().json; } catch (e) {}
if (!job) { try { job = $('Parse Telegram').first().json; } catch (e) {} }
if (!job) throw new Error('No pude recuperar el job ni de Parse Input ni de Parse Telegram');

// ---- perfil verificado
const rows = $input.all().map(i => i.json).filter(r => r && r.key);
if (!rows.length) throw new Error('profile_facts vino vacia: no genero nada con un perfil vacio');

const prof = {};
for (const r of rows) prof[r.key] = r.value;

const ORDER = [
  'identity', 'role_employer', 'employer_scope', 'employer_pipeline',
  'employer_crm', 'employer_alerting', 'role_side_project', 'stack', 'apis',
  'education', 'contact', 'experience_years', 'availability', 'title_rule',
  'salary_rule', 'red_flags_rule'
];
// _mercado no es un dato del perfil: es la referencia salarial y viaja aparte,
// para que el modelo no la confunda con algo que Santiago declaro sobre si mismo.
const keys = ORDER.filter(k => prof[k])
  .concat(Object.keys(prof).filter(k => !ORDER.includes(k) && k !== '_mercado'));
const PERFIL = 'PERFIL DE SANTIAGO (unica fuente de verdad):\n' +
  keys.map(k => '- ' + prof[k]).join('\n');

let yearsAvailable = 1.5;
const ym = String(prof.experience_years || '').match(/(\d+(?:[.,]\d+)?)/);
if (ym) yearsAvailable = parseFloat(ym[1].replace(',', '.'));

// ---- blockers
const LANGUAGE_REQUIRED = new RegExp(
  '\\(m\\s*\\/\\s*[wf]\\s*\\/\\s*d\\)' +
  '|(?:very good|good|fluent|native|excellent|strong|advanced|business|professional)\\s+' +
  '(?:german|deutsch|french|fran[cç]ais|dutch|nederlands|italian|italiano|' +
  'portuguese|portugu[eê]s|japanese|mandarin|chinese|korean|polish|swedish|norwegian)' +
  '|(?:german|french|dutch|italian|portuguese|japanese|mandarin|polish|swedish)\\s+' +
  '(?:language\\s+)?(?:skills|proficiency|fluency|required|is a must|mandatory)' +
  '|(?:fluency|fluent)\\s+in\\s+' +
  '(?:german|french|dutch|italian|portuguese|japanese|mandarin|polish|swedish)' +
  '|nivel\\s+(?:alto|nativo)\\s+de\\s+(?:alem[aá]n|franc[eé]s|italiano|portugu[eé]s)' +
  '|\\b(?:c1|c2|b2)\\s+(?:level\\s+)?(?:german|french|dutch|italian|portuguese)', 'i');

const RESIDENCY_LOCK = new RegExp(
  '(?:100%\\s+)?remote\\s+from\\s+(?:spain|germany|france|italy|poland|portugal|' +
  'netherlands|india|uk|the uk|canada|mexico|colombia|brazil)\\b' +
  '|(?:must|should)\\s+(?:be\\s+)?(?:resid\\w+|living|located|based)\\s+in\\s+' +
  '(?:spain|germany|france|italy|poland|portugal|netherlands|india|the uk|uk|canada|eu|europe)' +
  '|(?:spain|germany|france|italy|poland|portugal|netherlands|india|uk|canada|eu|europe|emea)[\\s-]only' +
  '|only\\s+(?:candidates|applicants)\\s+(?:from|based in|residing in|located in)' +
  '|(?:eu|european)\\s+(?:work\\s+)?(?:permit|citizenship|residency)\\s+(?:required|mandatory)' +
  '|right to work in the (?:uk|eu|netherlands|germany|spain)'
  // El aviso de RenegadesMedia decia "Fully Remote Opportunity within the
  // United States" y pasaba limpio: el patron solo miraba "remote FROM x".
  // "Remoto DENTRO de" es la misma restriccion escrita al reves.
  + '|remote\\s+(?:opportunity|position|role|work)?\\s*within\\s+the\\s+(?:united states|u\\.?s\\.?a?\\b)'
  + '|must\\s+(?:reside|be\\s+located|be\\s+based)\\s+(?:in|within)\\s+the\\s+(?:united states|u\\.?s\\.?a?\\b)'
  + '|(?:us|u\\.s\\.|united states)\\s+(?:residents?|citizens?|based candidates?)\\s+only'
  + '|authorized\\s+to\\s+work\\s+in\\s+the\\s+(?:united states|u\\.?s\\.?a?\\b)', 'i');

const NOT_ENGINEERING = new RegExp(
  'train(?:ing)?\\s+(?:the\\s+)?next[- ]generation\\s+ai' +
  '|help\\s+train\\s+ai\\s+(?:models|systems)' +
  '|shape\\s+how\\s+models\\s+learn' +
  '|no\\s+prior\\s+experience\\s+in\\s+ai\\s+is\\s+required' +
  '|your\\s+domain\\s+knowledge\\s+is\\s+what\\s+matters' +
  '|evaluate\\s+and\\s+enhance\\s+ai\\s+model\\s+capabilities' +
  '|(?:high[- ]quality|real[- ]world)\\s+(?:human\\s+)?(?:input|feedback|annotations?)\\s+' +
  '(?:for|to)\\s+(?:train|improve)' +
  '|data\\s+annotat(?:ion|or)|labeling\\s+(?:tasks|work)' +
  '|ai\\s+trainer\\b|rlhf\\s+contributor', 'i');

const BLOCKERS = [
  ['working language is not English or Spanish', LANGUAGE_REQUIRED],
  ['residency or work authorization lock', RESIDENCY_LOCK],
  ['AI training data work, not an engineering role', NOT_ENGINEERING]
];

const FOREIGN_STACKS = {
  'Microsoft/.NET': ['\\bc#', '\\.net\\b', 'azure functions', 'azure app service',
    'dynamics 365', 'dataverse', 'power platform', 'entra id',
    'semantic kernel', 'autogen', 'sharepoint', 'power automate'],
  'Java/JVM': ['\\bjava\\b', 'spring boot', '\\bkotlin\\b', '\\bscala\\b', 'hibernate', 'maven'],
  'Salesforce': ['\\bapex\\b', 'salesforce', 'lightning web', 'visualforce', 'soql'],
  'Ruby': ['\\bruby\\b', 'rails\\b', 'activerecord'],
  'PHP': ['\\bphp\\b', 'laravel', 'symfony', 'wordpress'],
  'Go/Rust/C++': ['\\bgolang\\b', '\\brust\\b', '\\bc\\+\\+'],
  'Data/ML research': ['pytorch', 'tensorflow', 'scikit-learn', 'model training',
    'fine[- ]tun\\w+ (?:models|llms)', 'mlops', 'feature store']
};

const HOME_STACK = ['\\bn8n\\b', 'make\\.com', 'zapier', 'supabase', 'postgres', 'node\\.?js',
  '\\bpython\\b', 'typescript', 'javascript', 'next\\.?js', '\\breact\\b',
  'webhook', 'rest api', '\\bdocker\\b', 'workflow automation', 'gohighlevel',
  '\\bllm\\b', 'openai', 'claude', 'ai agent', 'agentic'];

const FRICTIONS = [
  ['fixed working hours in another timezone',
    '\\d{1,2}\\s*(?::\\d\\d)?\\s*(?:am|pm)?\\s*(?:to|-|–)\\s*\\d{1,2}\\s*(?::\\d\\d)?\\s*' +
    '(?:am|pm)?\\s*(?:est|edt|pst|pdt|cst|cet|gmt|utc)|core hours|must overlap|overlap of at least'],
  ['time tracking software required',
    'time tracker|time[- ]tracking (?:software|tool)|hubstaff|timedoctor|screenshot'],
  ['unpaid or lengthy assessment',
    'take[- ]home (?:assignment|project|test)|series of assessments|unpaid (?:trial|test)|\\d+\\s*hour (?:assignment|assessment|task)'],
  ['customer facing seniority expected',
    'client[- ]facing|customer[- ]facing|stakeholder management|lead (?:the )?discovery'],
  ['on call or production support duty',
    'on[- ]call|pager duty|pagerduty|24/7|rotation'],
  ['equity or commission heavy compensation',
    'equity[- ]only|commission[- ]based|profit shar|revenue shar']
];

const blob = String(job.title || '') + '\n' + String(job.description || '');
const frictionsIdioma = [];
const low = blob.toLowerCase();
const count = (pats) => pats.reduce((n, p) => n + (new RegExp(p, 'i').test(low) ? 1 : 0), 0);
const evidence = (m) => {
  const s = Math.max(0, m.index - 70);
  const e = Math.min(blob.length, m.index + m[0].length + 70);
  return blob.slice(s, e).split(/\s+/).join(' ');
};

// Un idioma listado como deseable NO bloquea. El aviso de Clara decia
// "Portuguese proficiency (not required, but useful...)" y el screening lo mataba
// igual, porque el patron miraba "portuguese ... proficiency" sin leer alrededor.
// Un bloqueo tiene que significar "no podes tomar este trabajo", nunca "el aviso
// nombro un idioma". Cuando el contexto dice que es opcional, baja a friccion.
const OPCIONAL = new RegExp(
  'not\\s+required|nice[- ]to[- ]have|is\\s+a\\s+plus|a\\s+plus\\b|bonus|' +
  'preferred|desirable|desired|advantage(?:ous)?|would\\s+be\\s+great|' +
  'valorable|deseable|no\\s+excluyente|opcional|se\\s+valora|plus\\b', 'i');

const esOpcional = (m) => {
  // ventana generosa hacia atras (el "nice to have:" suele encabezar la lista)
  // y corta hacia adelante (el parentesis aclaratorio va pegado).
  const antes = blob.slice(Math.max(0, m.index - 220), m.index);
  const despues = blob.slice(m.index, Math.min(blob.length, m.index + m[0].length + 140));
  return OPCIONAL.test(antes) || OPCIONAL.test(despues);
};

const blockers = [];
for (const [label, pat] of BLOCKERS) {
  const m = pat.exec(blob);
  if (!m) continue;
  const idioma = label.indexOf('working language') === 0;
  if (idioma && esOpcional(m)) {
    frictionsIdioma.push({ reason: label.replace('is not', 'nombrado como deseable, no es'),
                           evidence: evidence(m) });
    continue;
  }
  blockers.push({ reason: label, evidence: evidence(m) });
}

const home = count(HOME_STACK);
const foreign = {};
for (const k of Object.keys(FOREIGN_STACKS)) foreign[k] = count(FOREIGN_STACKS[k]);
let worst = '', worstN = 0;
for (const k of Object.keys(foreign)) if (foreign[k] > worstN) { worst = k; worstN = foreign[k]; }
if (worstN >= 4 && worstN > home) {
  blockers.push({
    reason: 'stack mismatch, posting is ' + worst + ' heavy',
    evidence: worstN + ' ' + worst + ' signals against ' + home + ' matching your stack'
  });
}

const frictions = frictionsIdioma.slice();
for (const [label, pat] of FRICTIONS) {
  const m = new RegExp(pat, 'i').exec(blob);
  if (m) frictions.push({ reason: label, evidence: evidence(m) });
}

const YEARS = /(\d+)\s*(?:\+|to\s*\d+|-\s*\d+)?\s*(?:\+\s*)?years?[^.]{0,40}?(?:experience|exp\b|working|in\s+a|of)/gi;
const asked = [];
let ym2;
while ((ym2 = YEARS.exec(blob)) !== null) {
  const n = parseInt(ym2[1], 10);
  if (n <= 20) asked.push(n);
}
const yearsRequired = asked.length ? Math.max.apply(null, asked) : null;
if (yearsRequired && yearsRequired - yearsAvailable >= 2) {
  frictions.push({
    reason: 'asks ' + yearsRequired + ' years, you have about ' + yearsAvailable,
    evidence: 'gap of ' + (yearsRequired - yearsAvailable).toFixed(1) + ' years'
  });
}

const extId = String(job.url || ('cl-' + Date.now())).split('?')[0].substring(0, 255);

return [{
  json: Object.assign({}, job, {
    external_id: extId,
    _perfil: PERFIL,
    _mercado: prof._mercado || '',
    _profile_keys: keys,
    blocked: blockers.length > 0,
    block_reasons: blockers,
    frictions: frictions,
    years_required: yearsRequired,
    home_stack_signals: home,
    foreign_stack: foreign,
    screen_verdict: blockers.length ? 'blocked' : (frictions.length ? 'friction' : 'clear')
  })
}];

// Prep Blocked  (mode: runOnceForEachItem)
// Arma la fila y la respuesta para una oferta descartada, sin gastar una
// llamada a Claude.
const j = $input.item.json;
const reasons = (j.block_reasons || []).map(b => b.reason);
return {
  json: {
    mode: j.mode || 'apply',
    blocked: true,
    source: 'linkedin_blocked',
    external_id: j.external_id,
    title: String(j.title || 'Oferta').substring(0, 480),
    company: String(j.company || '').substring(0, 240),
    url: j.url || '',
    description: String(j.description || '').substring(0, 4000),
    score: 0,
    verdict: '',
    top_reasons: reasons,
    red_flags: (j.block_reasons || []).map(b => b.reason + ': ' + b.evidence),
    recommendation: '',
    salary_range: '',
    status: 'blocked',
    block_reasons: j.block_reasons || [],
    frictions: j.frictions || [],
    description_source: j.description_source || '',
    description_truncated: !!j.description_truncated
  }
};

// Validate Numbers  (mode: runOnceForEachItem)
// Entre Generate with Claude y Parse & Format.
//
// No descarta nada: extrae todo numero que el modelo escribio y lo contrasta
// contra PERFIL. Lo que no tiene respaldo viaja como unverified_numbers y se
// muestra arriba del mensaje, para que el problema se vea ANTES de que el texto
// termine pegado en una aplicacion real.

const resp = $input.item.json;
const perfil = $('Build Prompt').item.json._perfil || '';

const stopReason = resp.stop_reason || '';
const raw = (resp.content && resp.content[0] && resp.content[0].text) || '';

let parsed = null;
let parseError = '';
try {
  const m = String(raw).match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : raw);
} catch (e) {
  parseError = e.message;
}

// max_tokens es la causa mas comun de JSON cortado. Se reporta explicito en vez
// de dejar que JSON.parse tire un error sin contexto.
if (!parsed) {
  parsed = {
    job_title: '', company_name: '', language: 'es', fit_score: 0,
    top_reasons: [], red_flags: [], which_cv: 'EN', salary_note: '', salary_posted: '', salary_est: null,
    cover_letter: '', answers: []
  };
  if (stopReason === 'max_tokens') {
    parsed.top_reasons = ['La respuesta se corto por limite de tokens (max_tokens). Reduci la cantidad de preguntas o subi el limite.'];
  } else {
    parsed.top_reasons = ['El modelo no devolvio JSON valido: ' + parseError];
  }
}

// ---- numeros escritos por el modelo
const textos = [];
if (parsed.cover_letter) textos.push(String(parsed.cover_letter));
if (Array.isArray(parsed.answers)) {
  for (const a of parsed.answers) {
    if (a && a.answer) textos.push(String(a.answer));
  }
}
if (parsed.salary_note) textos.push(String(parsed.salary_note));

const NUM = /\d+(?:[.,]\d+)?/g;
const vistos = new Set();
const unverified = [];

for (let t of textos) {
  // lo que esta dentro de un placeholder no cuenta como afirmacion
  t = t.replace(/\[FALTA DATO[^\]]*\]/gi, ' ');
  let m;
  NUM.lastIndex = 0;
  while ((m = NUM.exec(t)) !== null) {
    const n = m[0];
    if (vistos.has(n)) continue;
    vistos.add(n);
    // respaldo = el numero aparece textual en PERFIL
    if (perfil.indexOf(n) === -1) {
      const s = Math.max(0, m.index - 40);
      const e = Math.min(t.length, m.index + n.length + 40);
      unverified.push({ number: n, context: t.slice(s, e).split(/\s+/).join(' ') });
    }
  }
}

return {
  json: {
    _llm: parsed,
    _stop_reason: stopReason,
    _parse_error: parseError,
    unverified_numbers: unverified,
    numbers_checked: vistos.size
  }
};

// Split Chunks  (mode: runOnceForAllItems)
// Un item por mensaje de Telegram. En modo score no hay chunks, devuelve [] y
// el nodo de Telegram directamente no corre.
let chunks = [];
try { chunks = $('Parse & Format').first().json.telegram_chunks || []; } catch (e) { chunks = []; }
return chunks.map((ch, i) => ({ json: { chunk: ch, i: i + 1, total: chunks.length } }));

// Sin esto el workflow moria en el nodo del modelo, nunca llegaba a un Respond
// to Webhook, y la extension recibia 200 con body vacio. El mensaje que mostraba
// entonces ("revisa que el workflow termine en un Respond to Webhook") mandaba a
// buscar un problema de configuracion que no existia.
//
// La forma del error de n8n es { error: { message, description, ... } }, no
// { message } pelado: leerlo mal devolvia "[object Object]" al usuario.
const j = $input.first().json || {};
const e = j.error || j;
const detalle = String(e.description || e.message || j.message || 'sin detalle').slice(0, 300);
const crudo = JSON.stringify(j);

let humano = detalle;
if (/usage limit/i.test(crudo)) {
  humano = 'La cuenta de Anthropic llego al limite de uso configurado. Subilo en ' +
           'Plans and Billing de console.anthropic.com. ' + detalle;
} else if (/credit balance/i.test(crudo)) {
  humano = 'La cuenta de Anthropic se quedo sin credito. Carga saldo en Plans and Billing.';
} else if (/rate.?limit|\b429\b/i.test(crudo)) {
  humano = 'Rate limit de la API. Espera unos segundos y volve a intentar.';
} else if (/timeout|ETIMEDOUT|ECONNRESET|socket hang up/i.test(crudo)) {
  humano = 'La llamada al modelo se corto por timeout. Volve a intentar.';
} else if (/overloaded|529/i.test(crudo)) {
  humano = 'La API esta sobrecargada en este momento. Volve a intentar en un minuto.';
}

return [{ json: { ok: false, error: humano, etapa: 'generate', detalle: detalle } }];
